// Emits db/002_catalog.sql from catalog.ts so the database and the code share one catalog.
import { NODES, INTAKE, CHANGE_ORDERS, PROFILE_FIELDS, isCoordination } from "./catalog.ts";
const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const arr = (a: string[]) => `'{${a.join(",")}}'`;
const ins = (head: string, rows: string[]) => `insert into ${head} values\n${rows.join(",\n")};`;
process.stdout.write([
  "-- Generated by core/src/seed.ts. Do not edit by hand.",
  ins("ws.node_def (id, kind)", NODES.map(n => `  (${q(n.id)}, ${q(isCoordination(n.id) ? "coordination" : "contingency")})`)),
  ins("ws.intake_def (id, kind, tier, core, asked_by)", INTAKE.map(i => `  (${q(i.id)}, ${q(i.kind)}, ${q(i.tier)}, ${i.core}, ${q(i.askedBy)})`)),
  ins("ws.change_order_def (id, name, low, high, clears, schedule)", CHANGE_ORDERS.map(c => `  (${q(c.id)}, ${q(c.name)}, ${c.low}, ${c.high}, ${arr(c.clears)}, ${q(c.schedule)})`)),
  ins("ws.profile_field_def (field, section, tier, agent_may)", PROFILE_FIELDS.map(f => `  (${q(f.field)}, ${q(f.section)}, ${q(f.tier)}, ${f.agentMay})`)),
].join("\n") + "\n");
